"use strict";

const KeyValueAdapter = require("../functions/adapterStore.js");

/**
 * MySQL adapter for CroxyDB.
 * @module adapters/mysql
 */

/**
 * @typedef {Object} MySQLDBOptions
 * @property {string} [url] MySQL connection URL.
 * @property {string} [host="localhost"] MySQL host.
 * @property {number} [port=3306] MySQL port.
 * @property {string} [user] MySQL user.
 * @property {string} [password] MySQL password.
 * @property {string} [database] MySQL database name.
 * @property {string} [table="croxydb"] Table used by CroxyDB.
 * @property {Object} [pool] Existing mysql2 pool.
 * @property {boolean} [waitForConnections=true] mysql2 pool option.
 * @property {number} [connectionLimit=10] mysql2 pool option.
 * @property {number} [queueLimit=0] mysql2 pool option.
 * @property {string} [seperator="."] Nested-key separator.
 */

/**
 * Stores CroxyDB values in a MySQL table as JSON strings.
 * @class
 * @extends KeyValueAdapter
 */
class MySQLDB extends KeyValueAdapter {
  /**
   * Creates a MySQL adapter.
   * @param {MySQLDBOptions} [options={}] Adapter options.
   */
  constructor(options = {}) {
    super(options);
    this.options = options;
    this.table = options.table || options.dbName || "croxydb";
    this.pool = options.pool || null;
    this.ready = false;
  }

  /**
   * Creates the pool when needed and ensures the table exists.
   * @returns {Promise<void>}
   */
  async init() {
    if (this.ready) return;

    if (!this.pool) {
      let mysql;
      try {
        mysql = require("mysql2/promise");
      } catch (error) {
        throw new TypeError("You must install \"mysql2\" module to use the MySQL adapter.");
      }

      this.pool = this.options.url
        ? mysql.createPool(this.options.url)
        : mysql.createPool({
          host: this.options.host || "localhost",
          port: this.options.port || 3306,
          user: this.options.user,
          password: this.options.password,
          database: this.options.database,
          waitForConnections: this.options.waitForConnections !== false,
          connectionLimit: this.options.connectionLimit || 10,
          queueLimit: this.options.queueLimit || 0
        });
    }

    await this.pool.query(
      `CREATE TABLE IF NOT EXISTS \`${this.table}\` (
        \`key\` VARCHAR(191) NOT NULL PRIMARY KEY,
        \`value\` LONGTEXT NOT NULL,
        \`updated_at\` TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
      )`
    );
    this.ready = true;
  }

  /**
   * Reads a root key from MySQL.
   * @param {string} key Root key.
   * @returns {Promise<*>}
   */
  async readValue(key) {
    await this.init();
    const [rows] = await this.pool.query(`SELECT \`value\` FROM \`${this.table}\` WHERE \`key\` = ? LIMIT 1`, [key]);
    if (!rows || rows.length < 1) return undefined;
    return JSON.parse(rows[0].value);
  }

  /**
   * Writes a root key to MySQL.
   * @param {string} key Root key.
   * @param {*} value Value to write.
   * @returns {Promise<void>}
   */
  async writeValue(key, value) {
    await this.init();
    await this.pool.query(
      `INSERT INTO \`${this.table}\` (\`key\`, \`value\`) VALUES (?, ?)
       ON DUPLICATE KEY UPDATE \`value\` = VALUES(\`value\`)`,
      [key, JSON.stringify(value)]
    );
  }

  /**
   * Deletes a root key from MySQL.
   * @param {string} key Root key.
   * @returns {Promise<void>}
   */
  async deleteValue(key) {
    await this.init();
    await this.pool.query(`DELETE FROM \`${this.table}\` WHERE \`key\` = ?`, [key]);
  }

  /**
   * Reads all root keys from MySQL.
   * @returns {Promise<Object>}
   */
  async readAllValues() {
    await this.init();
    const [rows] = await this.pool.query(`SELECT \`key\`, \`value\` FROM \`${this.table}\``);
    const result = {};
    rows.forEach((row) => {
      result[row.key] = JSON.parse(row.value);
    });
    return result;
  }

  /**
   * Clears all CroxyDB rows from the MySQL table.
   * @returns {Promise<void>}
   */
  async clearValues() {
    await this.init();
    await this.pool.query(`DELETE FROM \`${this.table}\``);
  }
}

module.exports = MySQLDB;
